+    return false;
+  }
+  skim++;
+  note("SKIM " + skim + " - CONDITION " + condition + " MUST EXIST IN THE CONTROL CONDITION TABLE");
+  conditionNotes();
+  if (skimFlushWord !== "") block([skimFlushWord]);
+  block([condition]);
+  return true;
